function calcValues() {
	const s = ~~(S * 0.69);
	x[0] = random(width/2 - s/2, width/2 + s/2);
	y[0] = random(height/2 - s/2, height/2 + s/2);
	rad[0] = random(10, 99);

	for (let i = 1; i < NUM; i++) {
		for (let r = 0; r < 99999; r++) {
			asd = 1;

			const newX = random(width/2 - s/2, width/2 + s/2);
			const newY = random(height/2 - s/2, height/2 + s/2);

			let newR = 400;

			for (let j = 0; j < i; j++) {
				const dst = dist(x[j], y[j], newX, newY);
				if (dst <= rad[s]) { // rad[j]
					asd--;
				}
				const ju = dst - rad[j];
				if (newR > ju) {
					newR = ju;
				}
			}

			if (asd > 0) {
				x[i] = newX;
				y[i] = newY;
				rad[i] = newR;
				break;
			}
		}

	}
}

