// inner circles happy accident, see #18

let epiColors; // https://github.com/epibyte/p5-epi-colors

let NUM = 150, S;
let easing = 0.1;

let x = new Array(NUM).fill(0);
let y = new Array(NUM).fill(0);
let xxx = new Array(NUM).fill(0);
let yyy = new Array(NUM).fill(0);
let rade = new Array(NUM).fill(0);
let rad = new Array(NUM).fill(0);

function setup() {
	createCanvas(windowWidth, windowHeight);
	S = max(width, height);
	rectMode(CENTER);
	noFill();
	noStroke();

	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors();
	epiColors.getRandomPalette();
	// console.log(epiColors.palette);

	for (let i = 0; i < NUM; i++) {
		rad[i] = 0;
		x[i] = width/2;
		y[i] = height/2;
	}

	calcValues();
}

function mousePressed() {
	calcValues();
}

function draw() {
	if (frameCount % 65 == 0) {
		calcValues();
	}

	background(8);

	// scale(0.4);
	// translate(width/2, height/2);

	for (let i = 0; i < NUM; i++) {
		xxx[i] = xxx[i] + (x[i] - xxx[i]) * easing;
		yyy[i] = yyy[i] + (y[i] - yyy[i]) * easing;
		rade[i] = rade[i] + (rad[i] - rade[i]) * easing;

		fill(epiColors.palette[i % epiColors.palette.length]);
		ellipse(xxx[i], yyy[i], rade[i] * 2, rade[i] * 2);
		// ellipse(xxx[i] - rade[i] / 2.2, yyy[i] - rade[i] / 2.2, rade[i] / 4, rade[i] / 4);
	}
}
